/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDimInventDimension10 extends UPSPricingAttributeInventDim implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventDimension10);
}

public Set getAllowedValues()
{
    var       ret = new Set(Types::Real);
    InventDim inventDim;

    while select inventDim
        group by InventDimension10
    {
        if (! ret.in(inventDim.InventDimension10))
        {
            ret.add(inventDim.InventDimension10);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventDimension10));
    qbr.value(queryValue(_value));
}
